            const propId = triggered[0].prop_id;
            // Extract the index from the button ID like "{'type':'btn-copy-error','index':2}.n_clicks"
            const match = propId.match(/index":(\\d+)/);
            if (!match) { return window.dash_clientside.no_update; }

